#include <bits/stdc++.h>
using namespace std;

#define ll long long

ll dp[262144 + 5][18];
int gdp, n, nw[262144 + 5];
int coun[20], s[20], tot;

int get(int mask)
{
    return (mask & gdp) ? 0 : 1;
}

int nw_dp_func(int mask)
{
    if (nw[mask] != -1) return nw[mask];

    for (int i = tot - 1; i >= 0; i--) {
        if (mask & (1 << i)) return nw[mask] = i;
    }

    return -1;
}

ll dp_func(int mask, int len)
{
    if (len == -1) return get(mask);

    if (dp[mask][len] != -1) return dp[mask][len];

    ll ret = 0;
    for (int i = 0; i < n; i++) {
        int v = mask & s[i];
        if (v == 0) continue;

        int f = nw_dp_func(v);
        ret += dp_func(mask ^ (1 << f), len - 1);
    }

    return dp[mask][len] = ret;
}

char str[20];
int rev[20];

int main()
{
    scanf("%s", str);
    tot = strlen(str);

    if (tot == 19) {
        cout << 1 << '\n';
        return 0;
    }

    for (int i = 0; str[i]; i++) {
        coun[str[i] - '0']++;
    }

    int f = tot - 1;
    for (int i = 0; i < 10; i++) {
        if (coun[i] == 0) continue;

        gdp |= (1 << f);
        int l = coun[i];

        while (l--) {
            s[n] |= (1 << f);
            f--;
        }

        rev[n] = i;
        n++;
    }

    memset(dp, -1, sizeof(dp));
    memset(nw, -1, sizeof(nw));

    ll ret = 0;
    int all = (1 << tot) - 1;

    for (int i = 0; i < tot; i++) {
        for (int j = 0; j < n; j++) {
            if (rev[j] == 0) continue;

            int f = nw_dp_func(s[j]);
            ret += dp_func(all ^ (1 << f), i - 1);
        }
    }

    cout << ret << '\n';
    return 0;
}

